from __future__ import annotations

import logging
from typing import Any

from app.config import Settings, get_settings
from app.store.db import Database
from app.sync.feishu_schema import (
    action_shell_from_task,
    row_to_asin_fields,
    task_to_fields,
)

logger = logging.getLogger(__name__)

# Columns that belong to system sync (never "human" fields in local schema)
SYSTEM_COLUMNS = {
    "biz_date",
    "marketplace",
    "shop_name",
    "shop_id",
    "asin",
    "parent_asin",
    "sku",
    "msku",
    "title",
    "title_cn",
    "brand",
    "open_date",
    "product_grade",
    "owner",
    "sale_price",
    "sale_num",
    "order_num",
    "avg_sale_price",
    "sale_price_change_pct",
    "order_num_change_pct",
    "sessions",
    "sessions_change_pct",
    "page_view",
    "conversion_rate",
    "conversion_rate_change_pp",
    "buy_box_percent",
    "ad_impression",
    "ad_clicks",
    "ad_ctr",
    "ad_cost",
    "ad_cost_change_pct",
    "cpc",
    "acos",
    "ad_sales",
    "available",
    "in_transit",
